      "kurz": "Haiti ist ein kleines Land in der Karibik mit einer ganz besonderen Geschichte: Es war das erste Land der Welt, das durch einen Sklavenaufstand frei wurde – und bei der WM 2026 ist es nach 52 Jahren wieder dabei!",
      "lang": "Haiti liegt in der Karibik auf der Insel Hispaniola, die es sich mit der Dominikanischen Republik teilt. Haiti hat eine einzigartige Geschichte: Im Jahr 1804 wurde es zum ersten Land der Welt, das durch einen Sklavenaufstand seine Unabhängigkeit erkämpfte – das ist heute noch eine Quelle des Nationalstolzes. Das Land ist bekannt für seine bunte Malerei und Volkskunst, aber auch für schwierige Lebensbedingungen durch Naturkatastrophen und Armut. Die meisten Haitianer sprechen Haitianisch Kreolisch – eine Mischung aus Französisch und westafrikanischen Sprachen. Viele Haitianer leben heute in Frankreich, den USA und Kanada – das spiegelt sich auch im Fußballkader wider, der fast vollständig aus Spielern der Diaspora besteht!"
