      "lang": "Schottland ist ein Land mit wilder Natur: Im Norden erstrecken sich die Highlands mit zerklüfteten Bergen, tiefen Seen (Lochs) und kleinen Inseln. Der bekannteste See ist Loch Ness – dort soll angeblich das Seeungeheuer „Nessie” leben! Die Hauptstadt Edinburgh ist berühmt für ihr imposantes Schloss, das hoch auf einem Felsen thront, und das jährliche Fringe Festival, eines der größten Kunstfestivals der Welt. Schottland gilt als Heimat des Golfs – das Spiel soll hier im 15. Jahrhundert erfunden worden sein. Und natürlich: Scotch Whisky aus Schottland ist weltweit berühmt. Typisch schottisch ist auch der Dudelsack (Bagpipe) und der Kilt – der karierte Rock, den Männer zu Festlichkeiten tragen."
