      "lang": "Paraguay liegt genau in der Mitte Südamerikas und hat keinen Zugang zum Meer. Trotzdem ist es bekannt für einen der spektakulärsten Wasserfälle der Welt – die Iguazú-Wasserfälle liegen zwar auf der Grenze zu Brasilien und Argentinien, gehören aber zu den Naturwundern dieser Region. Das Land hat zwei offizielle Sprachen: Spanisch und Guaraní – Guaraní ist die Sprache der indigenen Guaraní-Völker und wird von über 90 % der Bevölkerung gesprochen. Das ist etwas ganz Besonderes! Auf der Grenze zu Brasilien steht der Itaipú-Staudamm – lange Zeit das größte Wasserkraftwerk der Welt. Typisch paraguayisch ist der Genuss von Mate-Tee, einem kräftigen Kräutertee aus einem Kürbis. Und die Flagge Paraguays ist die einzige der Welt, die auf Vorder- und Rückseite unterschiedliche Motive hat!"
