      "lang": "Ecuador liegt genau am Äquator – der unsichtbaren Linie, die die Erde in eine nördliche und eine südliche Hälfte teilt. Davon hat das Land sogar seinen Namen! Die Hauptstadt Quito liegt auf über 2.800 Metern Höhe in den Anden – eine der höchstgelegenen Hauptstädte der Welt. Im Osten beginnt der Amazonas-Regenwald mit einer unglaublichen Artenvielfalt. Vor der Küste liegen die Galápagos-Inseln, wo Charles Darwin Tiere entdeckte, die ihn zu seiner berühmten Evolutionstheorie inspirierten. Ecuador ist der weltgrößte Bananenexporteur – ein Großteil der Bananen in deutschen Supermärkten kommt von dort! Und bei Kakao und Blumen ist Ecuador ebenfalls Weltspitze."
