      "lang": "Neuseeland liegt ganz weit weg im Südpazifik – fast am anderen Ende der Welt von Deutschland aus! Das Land besteht aus zwei Hauptinseln und hunderten kleinerer Inseln. Die Nordinsel hat aktive Vulkane und heiße Geysire, die Südinsel beeindruckt mit schneebedeckten Alpen und Fjorden, die wie aus einem Fantasy-Film aussehen – kein Wunder, dass Peter Jackson die Herr-der-Ringe-Trilogie dort drehte! Die Ureinwohner Neuseelands sind die Māori – ihre Kultur mit dem Haka-Tanz, Tätowierungen (Tā moko) und Holzschnitzereien ist weltweit bekannt. Und Kiwis? Das sind nicht nur die leckeren Früchte, sondern auch flugunfähige Vögel – Neuseelands Nationaltier! Das Rugbyteam 'All Blacks' gilt als das erfolgreichste Nationalteam aller Sportarten weltweit."
