      "kurz": "Spanien ist eine der erfolgreichsten Fußballnationen der Welt – Weltmeister 2010 und viermaliger Europameister! Und mit Lamine Yamal hat Spanien den aufregendsten Jungspieler der Welt.",
      "lang": "Spanien liegt auf der Iberischen Halbinsel im Südwesten Europas und ist bekannt für seine Sonne, Strände und lebendige Kultur. Die Hauptstadt Madrid und Barcelona sind zwei der bekanntesten Städte der Welt – nicht zuletzt wegen ihrer Fußballklubs Real Madrid und FC Barcelona, die zu den berühmtesten Vereinen der Welt gehören. Der Architekt Antoni Gaudí hinterließ in Barcelona einzigartige Bauwerke – die Sagrada Família, eine riesige Basilika, wird seit 1882 gebaut und ist noch immer nicht fertig! Spanien ist auch das Land von Flamenco (einem leidenschaftlichen Tanz), leckeren Tapas und Paella. Und jedes Jahr gibt es in Buñol das verrückteste Fest Europas: La Tomatina – dabei werfen sich Tausende Menschen Tomaten!"
