      "kurz": "Der Irak liegt in Mesopotamien – dem Land zwischen Tigris und Euphrat, wo vor über 5.000 Jahren eine der ersten Hochkulturen der Menschheit entstand. Hier wurde das Schreiben erfunden!",
      "lang": "Der Irak liegt zwischen den Flüssen Tigris und Euphrat – das Land heißt deshalb Mesopotamien, was auf Griechisch 'Land zwischen den Flüssen' bedeutet. Vor über 5.000 Jahren entstanden hier die ersten Städte der Welt, die ersten Gesetze und die erste Schrift (Keilschrift)! Das antike Babylon, einst eine der größten Städte der Welt, lag im heutigen Irak. Die sagenumwobenen Hängenden Gärten von Babylon gelten als eines der sieben Weltwunder der Antike. Der Gilgamesch-Epos, das älteste literarische Werk der Menschheit, wurde ebenfalls hier in Mesopotamien verfasst – vor über 4.000 Jahren! Heute ist der Irak ein Erdölland mit riesigen Vorkommen. Datteln – die süßen Früchte der Dattelpalme – exportiert der Irak in alle Welt."
