      "lang": "Norwegen liegt ganz oben in Nordeuropa, zwischen dem Atlantik und Skandinavien. Das Land ist berühmt für seine spektakulären Fjorde – das sind tiefe, von Gletschern ausgehöhlte Meeresarme, die sich bis weit ins Gebirge erstrecken. Der Geirangerfjord und der Nærøyfjord gehören zum UNESCO-Welterbe. Im Norden, hinter dem Polarkreis, kann man im Winter die faszinierenden Nordlichter (Aurora Borealis) sehen – bunte Lichtvorhänge am Himmel. Die Wikinger, die vor über 1.000 Jahren von Norwegen aus in alle Welt segelten, sind bis heute ein Symbol des Landes. Norwegen ist auch ein Ski-Paradies: Kein Land gewinnt bei Olympischen Winterspielen mehr Medaillen! Und in der Gegenwart ist Erling Haaland das Aushängeschild des Landes – einer der besten Fußballer der Welt."
