      "lang": "Senegal liegt ganz im Westen Afrikas, am Atlantischen Ozean – Dakar ist der westlichste Punkt des afrikanischen Kontinents! Das Land ist bekannt für sein Wort 'Teranga', das auf Wolof Gastfreundschaft bedeutet – kein Wunder, dass auch der Spitzname der Nationalmannschaft dieses Wort trägt. Besonders bekannt ist Senegal auch für die Gorée-Insel: Von dieser kleinen Insel vor Dakar wurden Jahrhunderte lang versklavte Menschen nach Amerika verschifft. Heute ist sie UNESCO-Welterbe und ein wichtiger Erinnerungsort. Die Baobab-Bäume, riesige dicke Bäume, die Jahrtausende alt werden können, sind das Symbol Senegals. Und die Dakar-Rallye – das härteste Geländerennen der Welt – trägt den Namen der Hauptstadt, obwohl es heute gar nicht mehr in Senegal stattfindet."
