      "lang": "Kroatien liegt an der wunderschönen Adriaküste und hat über 1.000 Inseln! Die Plitvicer Seen im Landesinneren mit türkisblauen Wasserfällen und Seen gehören zum UNESCO-Welterbe. Die Altstadt von Dubrovnik mit ihren mittelalterlichen Stadtmauern am Meer ist weltbekannt – auch als Kulisse für die Fantasyserie 'Game of Thrones'! Eine kroatische Erfindung, die wir alle kennen: die Krawatte! Kroatische Soldaten trugen im 17. Jahrhundert bunte Halstücher – daraus wurde die Krawatte. Im Fußball ist Kroatien ein Riese: Trotz nur 4 Millionen Einwohnern dreimal WM-Halbfinale – das schafft kein anderes Land der Welt! Luka Modrić, der kreativste Mittelfeldspieler seiner Generation, räumte 2018 den Ballon d'Or ab."
